using System;using System.Linq;using System.Reflection;using UnityEngine;using Codice.Expedition;using Codice.Mechanics;
public static class VerifyWisp{public static string Run(){var r=RunDirector.Instance;var w=UnityEngine.Object.FindObjectsByType<DescentCompanion>().First(x=>x.Wisp);r.Player.State.SpendMana(20);float before=r.Player.State.Mana;typeof(DescentCompanion).GetField("cooldown",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(w,0f);typeof(DescentCompanion).GetMethod("Update",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(w,null);float gain=r.Player.State.Mana-before;if(Mathf.Abs(gain-4)>.001f)throw new Exception("Pet mana: "+gain);return "PASS Lumbre restores exactly 4 mana during combat";}}
